  function box(w,h,d,x,y,z,material){const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);mesh.position.set(x,y,z);scene.add(mesh);return mesh}
  box(85,.3,36,0,-.2,8,stone);box(85,15,.6,0,7.3,-1.4,roomMaterial);box(85,.5,30,0,10,-1,roomMaterial);
  const stripMaterial=new THREE.MeshBasicMaterial({color:settings.accent});
  for(let i=0;i<9;i++){const x=i*10-40;box(.65,10,1,x,4.8,-.2,roomMaterial);box(.035,.025,30,x,.005,9,brass);box(8,.025,.06,x+5,.015,5,brass);box(7,.05,.15,x+5,8,-.8,stripMaterial)}
  const hemi=new THREE.HemisphereLight('#d9e7f1','#695441',.8);scene.add(hemi);const key=new THREE.DirectionalLight('#fff0d5',1.1);key.position.set(2,9,12);scene.add(key);
  const spots=projects.map((p,i)=>{const light=new THREE.SpotLight('#ffe5bf',90,24,.65,.85,1.6);light.position.set(xFor(i),8,4);light.target.position.set(xFor(i),3.5,-1);scene.add(light,light.target);return light});
  const loader=new THREE.TextureLoader(),materials=[],anchors=[],imageUrls=[];
  function poster(p){const c=document.createElement('canvas');c.width=1000;c.height=600;const ctx=c.getContext('2d');ctx.fillStyle='#172b33';ctx.fillRect(0,0,1000,600);ctx.fillStyle='#caa879';ctx.font='500 22px "Juho Sans", sans-serif';ctx.fillText(p.type,65,85);ctx.fillStyle='#f0eee4';ctx.font='600 68px "Juho Sans", sans-serif';ctx.fillText(p.title,65,300,860);ctx.fillStyle='#91a8af';ctx.font='400 25px "Juho Sans", sans-serif';ctx.fillText(p.subtitle,65,365,860);ctx.fillStyle='#caa879';ctx.font='400 24px sans-serif';ctx.fillText('EXHIBIT '+p.number,65,535);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return t;}
  const screenMaterial=()=>new THREE.MeshBasicMaterial({color:'#677773'});
  projects.forEach((p,i)=>{const x=xFor(i);box(7.45,4.7,.23,x,3.9,-.55,brass);box(7.2,4.45,.25,x,3.9,-.4,new THREE.MeshBasicMaterial({color:'#0e1216'}));const material=screenMaterial();materials.push(material);box(6.9,4.1,.04,x,3.9,-.24,material);box(3.4,.32,1.6,x,.5,1.5,roomMaterial);box(3.5,.04,1.7,x,.68,1.5,brass);
    const anchor=document.createElement('a');anchor.className='museum-art-link';anchor.href=getHref(p);anchor.dataset.worldProject=p.id;anchor.setAttribute('aria-label',p.title+' 전시 입장');const label=document.createElement('span');label.className='museum-label';const number=document.createElement('small');number.textContent='EXHIBIT '+p.number;const title=document.createElement('strong');title.textContent=p.title;label.append(number,title);anchor.append(label);anchor.addEventListener('dragstart',e=>e.preventDefault());anchor.addEventListener('click',e=>{if(suppress){e.preventDefault();return}if(!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey){e.preventDefault();enter(p.id)}});container.append(anchor);anchors.push(anchor);
  });
  const mascot=document.createElement('img');mascot.className='museum-mascot';mascot.alt='';mascot.setAttribute('aria-hidden','true');mascot.draggable=false;container.append(mascot);let walkX=xFor(3)+2;
  const veil=document.createElement('div');veil.className='entry-veil';veil.hidden=true;const caption=document.createElement('strong'),cancel=document.createElement('button');cancel.type='button';cancel.textContent='머무르기 · Esc';veil.append(caption,cancel);container.parentElement.append(veil);
  function cancelEntry(focus=false){if(!entry)return;clearTimeout(timer);const id=entry.id;entry=null;veil.hidden=true;container.parentElement.classList.remove('entering');if(focus)anchors[projects.findIndex(p=>p.id===id)]?.focus({preventScroll:true});request()}
  cancel.addEventListener('click',()=>cancelEntry(true));window.addEventListener('keydown',e=>{if(e.key==='Escape'&&entry){e.preventDefault();cancelEntry(true)}});window.addEventListener('pageshow',()=>cancelEntry());
  function enter(id){if(entry||!ids.includes(id))return;if(reduced){onOpen(id);return}onSelect(id);entry={id,start:performance.now(),duration:1200/settings.cameraSpeed};caption.textContent=projects.find(p=>p.id===id).title+'에 들어가는 중';veil.style.setProperty('--entry-progress',0);veil.hidden=false;container.parentElement.classList.add('entering');cancel.focus({preventScroll:true});timer=setTimeout(()=>onOpen(id),entry.duration);request()}
  const vector=new THREE.Vector3();function project(x,y,z){vector.set(x,y,z).project(camera);return [(vector.x*.5+.5)*container.clientWidth,(-vector.y*.5+.5)*container.clientHeight,vector.z]}
  function request(){dirty=true;if(active&&!frame)frame=requestAnimationFrame(draw)}
  function resize(){const w=container.clientWidth,h=container.clientHeight;if(!w||!h)return;camera.aspect=w/h;camera.fov=w<620?58:48;camera.updateProjectionMatrix();renderer.setSize(w,h,false);request()}
  function draw(now){frame=0;if(!active)return;const dt=Math.min((now-last)/1000||.016,.05);last=now;if(!reduced)elapsed+=dt;
    const x=xFor(selectedIndex()),distance=container.clientWidth<620?16:12.5;let z=distance/zoom,tx=x+2.4,ty=3.7;
    if(entry){const t=Math.min(1,(now-entry.start)/entry.duration),e=t*t*(3-2*t);z-=e*(z-3);tx=x+2.4*(1-e);ty=3.7+e*.2;veil.style.setProperty('--entry-progress',Math.max(0,(t-.65)/.35))}
    const blend=reduced?1:1-Math.exp(-dt*3.8*settings.cameraSpeed);target.set(tx+drag,ty,z);const moving=position.distanceTo(target)>.003;position.lerp(target,blend);camera.position.copy(position);look.lerp(new THREE.Vector3(x,3.65,0),blend);camera.lookAt(look);camera.updateMatrixWorld();
    anchors.forEach((anchor,i)=>{const x=xFor(i),a=project(x-3.65,6.15,0),b=project(x+3.65,1.45,0);anchor.hidden=!ids.includes(projects[i].id)||a[2]>1||b[0]<0||a[0]>container.clientWidth;anchor.style.left=a[0]+'px';anchor.style.top=a[1]+'px';anchor.style.width=Math.max(1,b[0]-a[0])+'px';anchor.style.height=Math.max(1,b[1]-a[1])+'px';anchor.classList.toggle('selected',projects[i].id===selected);anchor.setAttribute('aria-current',String(projects[i].id===selected))});
    const destination=x+2.7+Math.sin(elapsed*.5*settings.characterSpeed)*1.2,dir=destination-walkX;walkX+=reduced?x+2.7-walkX:Math.sign(dir)*Math.min(Math.abs(dir),dt*1.6*settings.characterSpeed);const [mx,my]=project(walkX,.15,3.7);mascot.hidden=!settings.characterVisible||!settings.character||!!entry||!ids.length;mascot.style.width=(container.clientHeight*.105*settings.characterSize)+'px';mascot.style.transform=`translate(${mx}px,${Math.min(my,container.clientHeight-90)-(reduced?0:Math.abs(Math.sin(elapsed*8*settings.characterSpeed))*3)}px) translate(-50%,-100%) scaleX(${dir<0?-1:1})`;
    if(dirty||moving||entry){renderer.render(scene,camera);dirty=false}if(!reduced||moving||entry)frame=requestAnimationFrame(draw);
  }
  function refreshContent(value){settings=value;roomMaterial.color.set(value.room);stripMaterial.color.set(value.accent);hemi.intensity=.8*value.lighting;key.intensity=1.1*value.lighting;spots.forEach(light=>{light.intensity=90*value.lighting;light.color.set(value.accent)});if(mascot.getAttribute('src')!==value.character)mascot.src=value.character;projects.forEach((p,i)=>{anchors[i].href=getHref(p);anchors[i].setAttribute('aria-label',p.title+' 전시 입장');anchors[i].querySelector('strong').textContent=p.title;const url=p.image||'',signature=url||p.title+'|'+p.subtitle;if(signature!==imageUrls[i]){imageUrls[i]=signature;if(!url){materials[i].map?.dispose();materials[i].map=poster(p);materials[i].color.set('#ffffff');materials[i].needsUpdate=true}else loader.load(url,texture=>{if(imageUrls[i]!==url){texture.dispose();return}texture.colorSpace=THREE.SRGBColorSpace;const aspect=texture.image.width/texture.image.height,ratio=6.9/4.1;if(aspect>ratio){texture.repeat.x=ratio/aspect;texture.offset.x=(1-texture.repeat.x)/2}else{texture.repeat.y=aspect/ratio;texture.offset.y=(1-texture.repeat.y)/2}materials[i].map?.dispose();materials[i].map=texture;materials[i].color.set('#ffffff');materials[i].needsUpdate=true;request()},undefined,()=>{materials[i].color.set('#526364');request()})}});request()}
  const surface=container.parentElement;
  surface.addEventListener('pointerdown',e=>{if(entry||e.button!==0||e.target.closest('button'))return;suppress=false;down={x:e.clientX,y:e.clientY,max:0}});
  surface.addEventListener('pointermove',e=>{if(!down)return;const dx=e.clientX-down.x,dy=e.clientY-down.y;down.max=Math.max(down.max,Math.hypot(dx,dy));if(Math.abs(dx)>10&&Math.abs(dx)>Math.abs(dy)){surface.setPointerCapture(e.pointerId);drag=-dx/container.clientWidth*7;request()}});
  const release=e=>{if(!down)return;const dx=e.clientX-down.x,dy=e.clientY-down.y;suppress=down.max>8;if(e.type==='pointerup'&&Math.abs(dx)>40&&Math.abs(dx)>Math.abs(dy)){const i=ids.indexOf(selected);onSelect(ids[Math.max(0,Math.min(ids.length-1,i+(dx<0?1:-1)))])}if(surface.hasPointerCapture(e.pointerId))surface.releasePointerCapture(e.pointerId);down=null;drag=0;request();setTimeout(()=>{suppress=false},0)};surface.addEventListener('pointerup',release);surface.addEventListener('pointercancel',release);
  let wheelTime=0;surface.addEventListener('wheel',e=>{if(e.ctrlKey||Math.abs(e.deltaX)<=Math.abs(e.deltaY)||entry||!ids.length)return;e.preventDefault();if(performance.now()-wheelTime<650)return;wheelTime=performance.now();const i=ids.indexOf(selected);onSelect(ids[Math.max(0,Math.min(ids.length-1,i+(e.deltaX>0?1:-1)))])},{passive:false});
